on conflict (id) do update set name = excluded.name;

-- Artist photos (Wikimedia Commons, credited) and newest covers
update public.artists a set image_url = coalesce(a.image_url, v.img), image_credit = case when a.image_url is null then v.credit else a.image_credit end,
  image_source = case when a.image_url is null then v.src else a.image_source end, artwork_url = coalesce(v.art, a.artwork_url),
  image_checked_at = coalesce(a.image_checked_at, now()),
  apple_id = case when a.apple_id is null and v.aid is not null and not exists (select 1 from public.artists x where x.apple_id = v.aid::bigint) then v.aid::bigint else a.apple_id end
